const EGO_COMERCIALES = { 88560: 'Carmen', 62597: 'Gisela', 10768: 'Laurence' };
// Llaves: en eGO solo constan las de algunos inmuebles. Con false, que no consten no
// impide ofrecer visita: se le dice a la asesora en el aviso para que lo coordine.
const LLAVES_OBLIGATORIAS = false;

// --- Tiempos -----------------------------------------------------------------
const BUFFER_SEGUNDOS = 60;         // se juntan los mensajes que el cliente manda seguidos
const RECORDATORIO_HORAS = 24;      // aviso al comercial antes de cada visita
// Antelacion minima para agendar desde WhatsApp. 0 = la que permita el horario.
const ANTELACION_MINIMA_HORAS = 0;
// Llamadas del asistente telefonico: todas van al panel, pero el aviso por
// WhatsApp a la comercial solo si la llamada ha durado al menos esto.
const LLAMADA_AVISO_MIN_SEGUNDOS = 15;

// Marca que llevan en la descripcion las visitas agendadas por WhatsApp. Con
// ella el recordatorio sabe cuales son suyas y no avisa de las del telefono.
const MARCA_ORIGEN = 'Origen: WhatsApp (Sara IA)';

// --- Pruebas -----------------------------------------------------------------
// Con estos telefonos el asistente funciona IGUAL que con un cliente, pero:
//   - los avisos van al que prueba (no a Carmen, Gisela ni Paco), con [PRUEBA];
//   - las visitas NO se escriben en la agenda real (se consulta de verdad, pero
//     la reserva se simula), asi no se ocupan huecos ni salta el recordatorio.
// Se rellena AL DESPLEGAR desde wa/pruebas.local.json (no esta en git), para no
// guardar telefonos personales en el repositorio.
const PRUEBAS = /*PRUEBAS*/{ telefonos: [], avisar_movil: '', avisar_email: '' }/*FIN_PRUEBAS*/;

// ---------------------------------------------------------------------------
// Utilidades
// ---------------------------------------------------------------------------
function normalizarTelefono(raw) {
  let s = String(raw ?? '').trim();
  const teniaMas = s.startsWith('+');
  s = s.replace(/\D/g, '');
  if (!teniaMas && s.startsWith('00')) s = s.slice(2);
  if (/^[6789]\d{8}$/.test(s)) s = '34' + s;
  return {
    e164: s ? '+' + s : '',
    wa_id: s,                                   // como lo quiere Meta: solo digitos
    nacional: s.startsWith('34') ? s.slice(2) : s,
    valido: s.length >= 8 && s.length <= 15,
  };
}

const sinAcentos = (s) => String(s ?? '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();

function prefijoDeReferencia(ref) {
  const m = String(ref ?? '').toUpperCase().match(/[A-Z]{2}/);
  return m ? m[0] : '';
}

// Asesora por referencia y, si no hay, por municipio. Si no hay ninguna, Laurence.
function resolverAsesora(ref, municipio) {
  const prefijo = prefijoDeReferencia(ref);
  let asesora = ASESORA_POR_PREFIJO[prefijo] || null;
  if (!asesora && municipio) {
    const m = sinAcentos(municipio);
    for (const [clave, quien] of Object.entries(ASESORA_POR_MUNICIPIO)) {
      if (m.includes(clave)) { asesora = quien; break; }
    }
  }
  const final = asesora || 'Laurence';
  return { prefijo, asesora, conocida: !!asesora, destinatario: final, ...EQUIPO[final] };
}

// Alquiler o compra. Mismo criterio que el telefono: lo dice la operacion o la
// referencia acaba en -A.
function esAlquiler(referencia, operacion) {
  const o = String(operacion ?? '').toLowerCase();
  if (o.includes('alquiler') || o.includes('traspaso') || o.includes('rent')) return true;
  if (o.includes('venta') || o.includes('compra')) return false;
  return /-A$/i.test(String(referencia ?? '').trim());
}

function detectarPortal(remitente, asunto) {
  for (const p of PORTALES) {
    if (p.de.test(String(remitente ?? '')) || p.asunto.test(String(asunto ?? ''))) return p.nombre;
  }
  return 'Otro';
}

// Meta no admite saltos de linea, tabuladores ni mas de 4 espacios seguidos
// dentro de un parametro de plantilla: si los hay, rechaza el envio entero.
function paramPlantilla(texto, max = 700) {
  return String(texto ?? '')
    .replace(/[\r\n\t]+/g, ' · ')
    .replace(/ {2,}/g, ' ')
    .trim()
    .slice(0, max) || '-';
}

// "2026-10-02" + "17:00" -> "jueves 2 de octubre a las 17:00"
function fechaLegible(fecha, hora) {
  const DIAS = ['lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado', 'domingo'];
  const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto',
                 'septiembre', 'octubre', 'noviembre', 'diciembre'];
  const d = DateTime.fromFormat(String(fecha), 'yyyy-MM-dd', { zone: ZONA });
  if (!d.isValid) return `${fecha} ${hora || ''}`.trim();
  return `${DIAS[d.weekday - 1]} ${d.day} de ${MESES[d.month - 1]}` + (hora ? ` a las ${hora}` : '');
}

// "Si, tengo que vender el mio" -> true. "No", "no necesito" -> false.
function esAfirmativo(texto) {
  const t = sinAcentos(texto).trim();
  if (!t || /^(no\b|nop|para nada|ninguna|nada)/.test(t) || /\bno (necesito|tengo|hace falta)\b/.test(t)) return false;
  return /^(si\b|sí\b|claro|por supuesto|correcto|exacto)/.test(t) ||
    /\b(tengo|necesito|debo|tendria|tendre|hay) que vender\b|\bnecesito vender\b|\bvender (primero|antes|mi|el|la)\b/.test(t);
}

// Id del agente de Chatwoot de un comercial ('Carmen' -> 5). 0 si no tiene.
function agenteDe(nombre) {
  return Number(AGENTES_CHATWOOT[String(nombre ?? '').trim()] || 0);
}

function esPrueba(telefono) {
  const t = normalizarTelefono(telefono).wa_id;
  return !!t && (PRUEBAS.telefonos || []).includes(t);
}

// Lo nuevo de leads y eGO (primer WhatsApp a los leads, notas en eGO) solo
// actua de verdad con MODO_LEADS = 'real'; con los telefonos de prueba, siempre.
function leadsEnReal(telefono) {
  return MODO_LEADS === 'real' || esPrueba(telefono);
}


// ===========================================================================
// LEADS ENTRANTES (web y eGO): que primer mensaje le toca a cada uno
// ---------------------------------------------------------------------------
// Se inyecta despues de config.js en los nodos que deciden la plantilla.
//
//   compra / alquiler con un inmueble DISPONIBLE -> bienvenida_compra / _alquiler
//                                                  ({{2}} = enlace del anuncio)
//   el inmueble ya NO esta disponible (vendido, reservado, retirado o fuera de
//   la cartera)                                  -> plantilla_abierta: ya no esta,
//                                                  y que Sara le ensena otros
//   compra / alquiler SIN inmueble (formulario general de la web)
//                                                -> plantilla_abierta con lo que busca
//   propietario que quiere vender o alquilar su vivienda
//                                                -> plantilla_abierta + aviso a la asesora
//   cualquier otra cosa                          -> nada: lo revisa una persona
// ===========================================================================

const TEXTOS_ABIERTA = {
  no_disponible: {
    es: (r) => `Soy Sara, IA de Casagencia. El inmueble por el que nos preguntaste${r.referencia ? ` (ref. ${r.referencia})` : ''} ya no está disponible, pero tenemos otros parecidos que te pueden encajar. ¿Quieres que te los enseñe por aquí?`,
    en: (r) => `I'm Sara, Casagencia's AI. The property you asked about${r.referencia ? ` (ref. ${r.referencia})` : ''} is no longer available, but we have similar ones that may suit you. Shall I show them to you here?`,
    fr: (r) => `Je suis Sara, l'IA de Casagencia. Le bien qui vous intéressait${r.referencia ? ` (réf. ${r.referencia})` : ''} n'est plus disponible, mais nous en avons d'autres similaires. Voulez-vous que je vous les montre ici ?`,
  },
  busqueda: {
    es: (r) => `Soy Sara, IA de Casagencia. Hemos recibido el mensaje que nos dejaste en nuestra web${r.resumen_cliente ? ` sobre ${r.resumen_cliente}` : ''}. ¿Te ayudo por aquí? Cuéntame qué buscas y te enseño lo que tenemos.`,
    en: (r) => `I'm Sara, Casagencia's AI. We received the message you left on our website${r.resumen_cliente ? ` about ${r.resumen_cliente}` : ''}. Can I help you here? Tell me what you are looking for and I'll show you what we have.`,
    fr: (r) => `Je suis Sara, l'IA de Casagencia. Nous avons bien reçu votre message sur notre site${r.resumen_cliente ? ` concernant ${r.resumen_cliente}` : ''}. Je peux vous aider ici : dites-moi ce que vous cherchez et je vous montre ce que nous avons.`,
  },
  propietario: {
    es: (r) => `Soy Sara, IA de Casagencia. Hemos recibido tu mensaje sobre tu vivienda${r.municipio ? ` en ${r.municipio}` : ''}. ${r.asesora} se pondrá en contacto contigo para hablarlo; si quieres, cuéntame por aquí cómo es.`,
    en: (r) => `I'm Sara, Casagencia's AI. We received your message about your property${r.municipio ? ` in ${r.municipio}` : ''}. ${r.asesora} will contact you to discuss it; meanwhile, feel free to tell me about it here.`,
    fr: (r) => `Je suis Sara, l'IA de Casagencia. Nous avons bien reçu votre message au sujet de votre bien${r.municipio ? ` à ${r.municipio}` : ''}. ${r.asesora} vous contactera pour en parler ; en attendant, vous pouvez m'en dire plus ici.`,
  },
};

// Idioma del mensaje del cliente (para la plantilla abierta). Por defecto, espanol.
function idiomaDe(texto) {
  const t = sinAcentos(texto);
  if (/\b(bonjour|je |j'|cordialement|merci|madame|monsieur|appartement|interesse)/.test(t)) return 'fr';
  if (/\b(hello|hi|dear|i am|i'm|i would|interested|thank|regards|please)\b/.test(t)) return 'en';
  return 'es';
}

const TIPOS_BUSCA = ['compra', 'alquiler', 'alquiler_temporada', 'sin_mensaje'];
const TIPOS_PROPIETARIO = ['vender_su_vivienda', 'alquilar_su_vivienda'];

// r: { tipo, referencia, disponible (true/false/null = no se sabe), enlace,
//      nombre, idioma, resumen_cliente, municipio, operacion }
function decidirPrimerMensaje(r) {
  const idioma = ['es', 'en', 'fr'].includes(r.idioma) ? r.idioma : 'es';
  const tipo = String(r.tipo || 'otro');
  const asesora = resolverAsesora(r.referencia, r.municipio).destinatario;
  const alquiler = tipo === 'alquiler' || tipo === 'alquiler_temporada' || esAlquiler(r.referencia, r.operacion);
  const nombre = String(r.nombre || '').trim().split(/\s+/)[0] || '';
  const base = { asesora, es_alquiler: alquiler, operacion: alquiler ? 'alquiler' : 'venta',
                 param1: paramPlantilla(nombre || '\u{1F44B}', 60) };
  const abierta = (clave, accion) => ({ ...base, accion, plantilla: PLANTILLAS.abierta.nombre,
    param2: paramPlantilla(TEXTOS_ABIERTA[clave][idioma]({ ...r, asesora }), 900) });

  if (TIPOS_PROPIETARIO.includes(tipo)) return abierta('propietario', 'captacion');
  if (r.referencia && r.disponible === false) return abierta('no_disponible', 'no_disponible');
  if (r.referencia && r.enlace && (TIPOS_BUSCA.includes(tipo) || tipo === 'otro' || !tipo)) {
    const p = alquiler ? PLANTILLAS.alquiler : PLANTILLAS.compra;
    return { ...base, accion: 'bienvenida', plantilla: p.nombre, param2: paramPlantilla(r.enlace, 300) };
  }
  if (TIPOS_BUSCA.includes(tipo)) return abierta('busqueda', 'busqueda');
  return { ...base, accion: 'revisar', plantilla: '', param2: '' };
}


// [WA] 5 · Leads de eGO · Decidir
// Un item por lead nuevo. Con el estado de su inmueble en eGO (GetRealestate,
// en el mismo orden) y la cartera publicada en la web (el enlace):
//   - disponible (estado 2 en eGO) -> bienvenida_compra / _alquiler con el enlace;
//   - reservado, vendido, alquilado, retirado... -> plantilla_abierta: ya no
//     esta disponible y Sara le ensena otros;
//   - la comercial que puso eGO y la que toca por la referencia (BN/OR Carmen,
//     CS/VR Gisela), para comprobar que coinciden.
const nuevos = $('SoloNuevos').all();
let inmuebles = [];
try { inmuebles = $('EstadoDelInmueble').all(); } catch (e) { inmuebles = []; }
let cartera = [];
try { cartera = $('LaCartera').first().json.filas || []; } catch (e) { cartera = []; }
if (typeof cartera === 'string') { try { cartera = JSON.parse(cartera); } catch (e) { cartera = []; } }
const porRef = Object.fromEntries([].concat(cartera).map(c => [String(c.ref || '').toUpperCase(), c]));

return nuevos.map((n, k) => {
  const b = n.json;
  const r = inmuebles[k]?.json || {};
  const inm = r.ok && r.datos && typeof r.datos === 'object' ? r.datos : {};
  const c = porRef[b.referencia] || {};
  const estadoId = Number(inm.realestateStatusId || 0);
  const estado = EGO_ESTADOS[estadoId] || (estadoId ? `estado ${estadoId}` : '');
  // Lo dice eGO; si eGO no ha contestado, que siga publicado en la web
  const disponible = !b.referencia ? null : (estadoId ? estadoId === EGO_DISPONIBLE : !!c.ref);
  const tel = normalizarTelefono(b.telefono);
  const alquiler = esAlquiler(b.referencia, b.operacion);
  const d = decidirPrimerMensaje({
    tipo: alquiler ? 'alquiler' : 'compra',
    referencia: b.referencia,
    disponible,
    // Si no esta en la web, la bienvenida lleva la referencia en vez del enlace
    enlace: c.enlace || (b.referencia ? `ref. ${b.referencia}` : ''),
    operacion: b.operacion,
    nombre: b.nombre,
    idioma: idiomaDe(b.mensaje),
    municipio: c.municipio || '',
  });
  const asignadoEgo = b.asignado_ids.map(id => EGO_COMERCIALES[id]).filter(Boolean)[0]
    || String(b.asignado_nombres[0] || '').split(' ')[0];
  const porReferencia = resolverAsesora(b.referencia, c.municipio).destinatario;
  return { json: {
    ...d,
    lead_id: b.lead_id,
    telefono_e164: tel.e164,
    telefono_wa: tel.wa_id,
    se_puede_contactar: tel.valido,
    // Se manda de verdad solo con MODO_LEADS = 'real' (o a un telefono de prueba)
    enviar: tel.valido && !!d.plantilla && leadsEnReal(tel.e164),
    nombre: b.nombre,
    email_cliente: b.email,
    referencia: b.referencia,
    enlace: c.enlace || '',
    portal: b.portal,
    solicitud: b.solicitud,
    tipo: alquiler ? 'alquiler' : 'compra',
    estado_inmueble: estado || (c.ref ? 'publicado en la web' : 'sin datos'),
    disponible,
    // eGO no crea contacto con los leads de los portales (potencialClientId vacio)
    contacto_creado: false,
    asignado_ego: asignadoEgo,
    asesora_por_referencia: porReferencia,
    asignacion_coincide: !asignadoEgo || asignadoEgo === porReferencia,
    notas: `Lead de eGO (${b.solicitud || b.portal}): ${b.mensaje || b.obs}`.slice(0, 1500),
    asunto: b.solicitud,
  }, pairedItem: { item: k } };
});

parameters.query:
update wa_leads
   set estado = 'plantilla_enviada', conversacion_id = $2, actualizado_en = now()
 where telefono_wa = $1 and referencia = $3;
